use std::collections::HashMap;

#[derive(Debug, Clone)]
struct Order {
    id: u32,
    amount: f64,
    status: &'static str,
}

fn main() {
    let orders = vec![
        Order { id: 101, amount: 250.0, status: "paid" },
        Order { id: 102, amount: 80.0, status: "pending" },
        Order { id: 103, amount: 420.5, status: "paid" },
        Order { id: 104, amount: 15.0, status: "paid" },
        Order { id: 105, amount: 999.0, status: "cancelled" },
    ];

    // ---- 1. 惰性求值演示：filter 只被调用必要次数 ----
    let mut filter_calls = 0usize;
    let total: f64 = orders
        .iter()
        .filter(|o| {
            filter_calls += 1;          // 统计闭包真实调用次数
            o.status == "paid"
        })
        .take(2)                        // 只要前两条已支付订单，之后立即停止拉取
        .map(|o| o.amount)
        .sum();
    println!("前两条已支付订单总额: {:.2}, filter 实际执行 {filter_calls} 次", total);

    // ---- 2. 过滤 + 收集到 HashMap（一次遍历完成） ----
    let big_orders: HashMap<u32, f64> = orders
        .iter()
        .filter(|o| o.amount > 100.0)
        .map(|o| (o.id, o.amount))
        .collect();
    println!("大额订单: {big_orders:?}");

    // ---- 3. try_fold：带错误、可提前中止的聚合 ----
    let checked = orders.iter().try_fold(0.0f64, |acc, o| {
        let next = acc + o.amount;
        if next > 1000.0 {
            Err(format!("订单 #{} 使累计金额超出预算 1000", o.id))
        } else {
            Ok(next)
        }
    });
    match checked {
        Ok(sum) => println!("累计金额: {:.2}", sum),
        Err(e)  => println!("聚合中止: {e}"),
    }

    // ---- 4. 自定义惰性适配器：滑动窗口 ----
    let deltas: Vec<f64> = windows(&orders, 2)
        .map(|pair| pair[1].amount - pair[0].amount)
        .collect();
    println!("相邻订单金额差: {deltas:?}");
}

/// 手写惰性适配器：每次产出 n 个元素的滑动窗口
fn windows<'a>(slice: &'a [Order], n: usize) -> impl Iterator<Item = &'a [Order]> {
    let mut start = 0;
    std::iter::from_fn(move || {
        if start + n <= slice.len() {
            let window = &slice[start..start + n];
            start += 1;
            Some(window)
        } else {
            None
        }
    })
}

